            for (unsigned int br = 0; br < t_ParEntries; ++br) {
#pragma HLS PIPELINE REWIND
                WideType<t_DataType, t_ParEntries> l_val;
                l_val = (i == j) ? p_inSymUpTransp.read() : (i < j) ?

p_inSymUpTransp.read() : (i < j) ? p_inForward.read() : p_inTransp.read();
                p_out.write(l_val);
            }
        }
    }
}

