    ap_uint<13> i, j, k, l;
    ap_uint<24> temp = (alpha * ((1 << 23) - 1));
    ap_uint<24> temp1 = ((1 << 23) - 1) - temp + 1;

    XF_TNAME(DST_T, NPC) pxl_pack_out;
    XF_TNAME(SRC_T, NPC) pxl_pack1, pxl_pack2;
RowLoop:
    for (i = 0; i < height; i++) {
// clang-format off
