    ap_int<26> S02 = A5 + A6;

    ap_int<26> S0 = S00 + S01;
    ap_int<26> S = S0 + S02;

    ap_int<32> res = ((S * XF_DIV_VAL_7x7) >> 15);

    g_y = (XF_PTNAME(DEPTH_SRC))res;
