template <int SRC_T,
          int DST_T,
          int ROWS,
          int COLS,
          int DEPTH_SRC,
          int DEPTH_DST,
          int NPC,
          int NPC1,
          int XFCVDEPTH_IN_1 = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_OUT_1 = _XFCVDEPTH_DEFAULT,
          int WORDWIDTH_SRC,
          int WORDWIDTH_DST>
void xFPackNMS(
    xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_1>& _src_mat, // hls::stream< XF_SNAME(WORDWIDTH_SRC) >& _src_mat,
    xf::cv::Mat<DST_T, ROWS, COLS, NPC1, XFCVDEPTH_OUT_1>& _dst_mat, // hls::stream< XF_SNAME(WORDWIDTH_DST)>& _dst_mat,
    uint16_t imgheight,
    uint16_t imgwidth) {
    int npcCols = imgwidth;
    int divNum = (int)(imgwidth / 32);
    int npcColsNxt = (divNum + 1) * 32;
    if (imgwidth % 32 != 0) {
        npcCols = npcColsNxt;
    }
    const int num_clks_32pix = 32 / NPC;

    int col_loop_count_ac = (imgwidth / NPC);
    int col_loop_count = (npcCols / NPC);
    // printf("col_loop_count:%d %d \n",col_loop_count_ac,col_loop_count);
    ap_uint<64> val;
    int read_ind = 0, write_ind = 0;
rowLoop:
    for (int i = 0; i < (imgheight); i++) {
// clang-format off
        #pragma HLS LOOP_TRIPCOUNT min=ROWS max=ROWS
        #pragma HLS LOOP_FLATTEN off
    // clang-format on

    colLoop:
        for (int j = 0; j < col_loop_count; j = j + (num_clks_32pix)) {
// clang-format off
            #pragma HLS LOOP_TRIPCOUNT min=COLS/32 max=COLS/32
            #pragma HLS pipeline
            // clang-format on

            for (int k = 0; k < num_clks_32pix; k++) {
// clang-format off
                #pragma HLS UNROLL
                // clang-format on
                if ((j + k) >= col_loop_count_ac) {
                    val.range(k * 2 * NPC + (NPC * 2 - 1), k * 2 * NPC) = 0; //_src_mat.read(read_ind++);
                } else {
                    val.range(k * 2 * NPC + (NPC * 2 - 1), k * 2 * NPC) = _src_mat.read(read_ind++);
                }
            }
            _dst_mat.write(write_ind++, val);
        }
    }
}

