    ap_uint<CLIP_COUNTER_BITS> mClipValue;

    CLAHETile(int height, int width, int clip, int tilesY, int tilesX)
        : mRows(height), mCols(width), mTilesY(tilesY), mTilesX(tilesX) {
#ifndef __SYNTHESIS__
