template <unsigned int MAXCORNERSNO,
          unsigned int TYPE,
          unsigned int ROWS,
          unsigned int COLS,
          unsigned int NPC,
          int XFCVDEPTH_IN = _XFCVDEPTH_DEFAULT>
void cornersImgToList(xf::cv::Mat<TYPE, ROWS, COLS, NPC, XFCVDEPTH_IN>& _src,
                      unsigned int list[MAXCORNERSNO],
                      unsigned int* ncorners) {
    int cornerCount = 0;
    for (unsigned short i = 0; i < _src.rows; i++) {
        for (unsigned short j = 0; j < _src.cols; j++) {
// clang-format off
            #pragma HLS PIPELINE
            // clang-format on
            ap_uint<8> tempValue = _src.read(i * _src.cols + j);
            if (tempValue == 255 && cornerCount < MAXCORNERSNO) // value is 255 if there's a corner
            {
                ap_uint<32> point;
                point.range(31, 16) = i;
                point.range(15, 0) = j;

                list[cornerCount] = (unsigned int)point;
                cornerCount++;
            }
        }
    }
    *ncorners = cornerCount;
    for (int i = cornerCount; i < MAXCORNERSNO; i++) {
// clang-format off
        #pragma HLS PIPELINE
        // clang-format on
        list[i] = 0;
    }
}
