 *************************************************************************/
// PackPixels
template <int WORDWIDTH>
XF_SNAME(WORDWIDTH)
PackPixels(ap_uint8_t* buf) {
    XF_SNAME(WORDWIDTH) val;
    for (int k = 0, l = 0; k < XF_WORDDEPTH(WORDWIDTH); k += 8, l++) {
// clang-format off
        #pragma HLS unroll
        // clang-format on
        // Get bits from certain range of positions.
        val.range(k + 7, k) = buf[l];
    }
    return val;
}

/**************************************************************************
 * Extract UYVY Pixels from input stream
 *************************************************************************/
// ExtractUYVYPixels
template <int WORDWIDTH>
void ExtractUYVYPixels(XF_SNAME(WORDWIDTH) pix, ap_uint8_t* buf) {
    int k;
    XF_SNAME(WORDWIDTH) val;
    int pos = 0;

    for (k = 0; k < (XF_WORDDEPTH(WORDWIDTH)); k += 8) {
// clang-format off
        #pragma HLS unroll
        // clang-format on			
		val = (XF_SNAME(WORDWIDTH))pix;
		uint8_t p;

		// Get bits from certain range of positions.
        p = val.range(k + 7, k);
        buf[pos++] = p;
    }
}

template <int SRC_T, int NPC, int WORDWIDTH>
void ExtractUYVYPixels(XF_SNAME(WORDWIDTH) pix, XF_CTUNAME(SRC_T, NPC) buf[]) {

    int k;
    XF_SNAME(WORDWIDTH) val;
    int pos = 0;
	const int STEP = XF_DTPIXELDEPTH(SRC_T, NPC);
	XF_CTUNAME(SRC_T, NPC) p;

    val = (XF_SNAME(WORDWIDTH))pix;
    for (k = 0; k < (XF_WORDDEPTH(WORDWIDTH)); k += STEP) {
// clang-format off
        #pragma HLS unroll
        // clang-format on
        // Get bits from certain range of positions.
        p = val.range(k + STEP - 1, k);
        buf[pos++] = p;
    }
}
