            g = imgblock[2][2 + loop];
            r = rgb_bgr_kernel<XF_DTUNAME(SRC_T, NPC), buf_size>(imgblock, loop);
        }
    } else {                           // if R row
        if ((col & 0x00000001) == 0) { // Odd row,

