template <int TYPE, int ROWS, int COLS, int NPC, int XFCVDEDPTH_IN, int WINDOW_SIZE>
static void readMatRows(xf::cv::Mat<TYPE, ROWS, COLS, NPC, XFCVDEDPTH_IN>& matB,
                        hls::stream<pix_t>& pixStream,
                        int rows,
                        int cols,
                        int size) {
    const int WORD_SIZE = (NPC == XF_NPPC1) ? 1 : 2;
    for (int i = 0; i < size; i++) {
// clang-format off
        #pragma HLS LOOP_TRIPCOUNT min=1 max=COLS*ROWS/NPC
        #pragma HLS PIPELINE
        // clang-format on
        mywide_t<XF_NPIXPERCYCLE(NPC)> tmpData;
        tmpData.data[0] = matB.read(i);

        // for (int k = 0; k < WORD_SIZE; ++k) {
        //    pixStream.write(tmpData.data[k]);
        // }
        pixStream.write(tmpData.data[0]);
    }
}

