            #pragma HLS UNROLL
            // clang-format on
            buf[i_row][i_col] = 0; // buf[K_ROWS>>1][i_col];
        }
    }

    int wr_ind = 0;
Row_Loop:
    for (row = (K_ROWS >> 1); row < img_height + (K_ROWS >> 1); row++) {
