        xfdilate<ROWS, COLS, XF_CHANNELS(TYPE, NPC), TYPE, NPC, XFCVDEPTH_IN_1, XFCVDEPTH_OUT_1, 0,
                 (COLS >> XF_BITSHIFT(NPC)) + (K_COLS >> 1), K_ROWS, K_COLS>(_src, _dst, imgheight, imgwidth, kernel);
    }

