template <int SRC_T,
          int N_ROWS,
          int N_COLS,
          int MAX_ROWS,
          int MAX_COLS,
          int NPPC = XF_NPPC1,
          int XFCVDEPTH_IN_1 = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_LEF = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_SEF = _XFCVDEPTH_DEFAULT,
          int USE_URAM = 0>
class ExposureFramesExtract {
   public:
    // Internal buffers, registers
    xf::cv::LineBuffer<N_ROWS,
                       ((MAX_COLS + N_COLS) >> (XF_BITSHIFT(NPPC))),
                       XF_TNAME(SRC_T, NPPC),
                       (USE_URAM ? RAM_S2P_URAM : RAM_S2P_BRAM),
                       (USE_URAM ? N_ROWS : 1)>
        buff;

    // Read and Write Pointer
    uint32_t fifo_rd_ptr;
    uint32_t fifo_wr_ptr;
    uint32_t src_rd_ptr;
    uint32_t lef_ptr;
    uint32_t sef_ptr;

    // ....................................................................................
    // Pointer initializer
    // ....................................................................................
    void initialize() {
// clang-format off
            #pragma HLS INLINE
        // clang-format on

        // Initialize read and write pointers
        fifo_rd_ptr = 0;
        fifo_wr_ptr = 0;

        src_rd_ptr = 0;

        lef_ptr = 0;
        sef_ptr = 0;

        return;
    }

    // ....................................................................................
    // Default Constructor
    // ....................................................................................
    ExposureFramesExtract() {
// clang-format off
            #pragma HLS INLINE
        // clang-format on

        initialize();
    }

    // ...............................................................................

...................................................................................
    ExposureFramesExtract() {
// clang-format off
            #pragma HLS INLINE
        // clang-format on

        initialize();
    }

    // ....................................................................................
    // Extraction function:
    //   This function synchronizes input frames of different exposures by storing initial
    //   blank lines into temporary buffer (BRAM or URAM)
    // ....................................................................................
    void extract(xf::cv::Mat<SRC_T, MAX_ROWS * 2, MAX_COLS + N_COLS, NPPC, XFCVDEPTH_IN_1>& _hdrSrc,
                 xf::cv::Mat<SRC_T, MAX_ROWS, MAX_COLS, NPPC, XFCVDEPTH_LEF>& _lefSrc,
                 xf::cv::Mat<SRC_T, MAX_ROWS, MAX_COLS, NPPC, XFCVDEPTH_SEF>& _sefSrc) {
// clang-format off
            #pragma HLS INLINE OFF
        // clang-format on

        // Constants for loopcounts
        const uint32_t _TC1 = N_ROWS - 1;
        const uint32_t _TC2 = MAX_ROWS - N_ROWS;
        const uint32_t _TC3 = MAX_COLS + N_COLS;
        // Initialize read and write pointers
        initialize();

    // Part-1: Collect initial blank lines of Long Exposure Frames (LEF)
    // -----------------------------------------------------------------
    BUFFER_LINES:
        for (int row = 0; row < N_ROWS - 1; row++) {
// clang-format off
#pragma HLS LOOP_TRIPCOUNT min = 1 max = _TC1
            // clang-format on
            for (int col = 0; col<_hdrSrc.cols>> (XF_BITSHIFT(NPPC)); col++) {
// clang-format off
                    #pragma HLS PIPELINE II=1
                    #pragma HLS LOOP_TRIPCOUNT min=1 max=_TC3/NPPC
                // clang-format on

                buff.val[fifo_wr_ptr][col] = _hdrSrc.read(src_rd_ptr++);
            }

            /*if (fifo_wr_ptr == N_ROWS - 1)
                fifo_wr_ptr = 0;
            else*/
            fifo_wr_ptr++;
        }

    // Part-2: Writing out LEF and SEF (Short Exposure Frames)
    // -----------------------------------------------------------------
    SPLIT_LINES:
        for (int row = N_ROWS - 1; row < _lefSrc.rows; row++) {
// clang-format off
#pragma HLS LOOP_TRIPCOUNT min = 1 max = _TC2
            // clang-format on
            // LEF (Long Exposure Frame's Line, into internal buffer)
            for (int col = 0; col<_hdrSrc.cols>> (XF_BITSHIFT(NPPC)); col++) {
// clang-format off
                    #pragma HLS PIPELINE II=1
                    #pragma HLS LOOP_TRIPCOUNT min=1 max=_TC3/NPPC

                // clang-format on

                buff.val[fifo_wr_ptr][col] = _hdrSrc.read(src_rd_ptr++);

                //_lefSrc.write(lef_ptr++, buff.val[fifo_rd_ptr][col]);
            }

            // SEF (Short Exposure Frame's Line, directly streamed out)
            for (int col = 0; col<_hdrSrc.cols>> (XF_BITSHIFT(NPPC));

rows; row++) {
// clang-format off
#pragma HLS LOOP_TRIPCOUNT min = 1 max = _TC2
            // clang-format on
            // LEF (Long Exposure Frame's Line, into internal buffer)
            for (int col = 0; col<_hdrSrc.cols>> (XF_BITSHIFT(NPPC)); col++) {
// clang-format off
                    #pragma HLS PIPELINE II=1
                    #pragma HLS LOOP_TRIPCOUNT min=1 max=_TC3/NPPC

                // clang-format on

                buff.val[fifo_wr_ptr][col] = _hdrSrc.read(src_rd_ptr++);

                //_lefSrc.write(lef_ptr++, buff.val[fifo_rd_ptr][col]);
            }

            // SEF (Short Exposure Frame's Line, directly streamed out)
            for (int col = 0; col<_hdrSrc.cols>> (XF_BITSHIFT(NPPC)); col++) {
// clang-format off
                    #pragma HLS PIPELINE II=1
                    #pragma HLS LOOP_TRIPCOUNT min=1 max=_TC3/NPPC
                // clang-format on

                if (col >= (N_COLS >> (XF_BITSHIFT(NPPC)))) {
                    _lefSrc.write(lef_ptr++, buff.val[fifo_rd_ptr][col]);
                    _sefSrc.write(sef_ptr++, _hdrSrc.read(src_rd_ptr++));
                } else {
                    // XF_TNAME(SRC_T, NPPC) dummy1 = buff.val[fifo_rd_ptr][col];
                    XF_TNAME(SRC_T, NPPC) dummy2 = _hdrSrc.read(src_rd_ptr++);
                }
            }

            // Handle read and write pointers:
            //    Reset them upon reaching end of the FIFO as it is a cyclic buffer
            if (fifo_wr_ptr == N_ROWS - 1)
                fifo_wr_ptr = 0;
            else
                fifo_wr_ptr++;

            if (fifo_rd_ptr == N_ROWS - 1)
                fifo_rd_ptr = 0;
            else
                fifo_rd_ptr++;
        }

    // Part-3: Get last N_ROWS of SEF
    // -----------------------------------------------------------------
    LAST_LINES:
        for (int row = 0; row < N_ROWS - 1; row++) {
// clang-format off
#pragma HLS LOOP_TRIPCOUNT min = 1 max = _TC1
            // clang-format on
            for (int col = 0; col<_hdrSrc.cols>> (XF_BITSHIFT(NPPC)); col++) {
// clang-format off
                    #pragma HLS PIPELINE II=1
                    #pragma HLS LOOP_TRIPCOUNT min=1 max=_TC3/NPPC
                // clang-format on

                //_lefSrc.write(lef_ptr++, buff.val[fifo_rd_ptr][col]);
                //_sefSrc.write(sef_ptr++, _hdrSrc.read(src_rd_ptr++));
                if (col >= (N_COLS >> (XF_BITSHIFT(NPPC)))) {
                    _lefSrc.write(lef_ptr++, buff.val[fifo_rd_ptr][col]);
                    _sefSrc.write(sef_ptr++, _hdrSrc.read(src_rd_ptr++));
                } else {
                    // XF_TNAME(SRC_T, NPPC) dummy1 = buff.val[fifo_rd_ptr][col];
                    XF_TNAME(SRC_T, NPPC) dummy2 = _hdrSrc.read(src_rd_ptr++);
                }
            }

            if (fifo_rd_ptr == N_ROWS - 1)
                fifo_rd_ptr = 0;
            else
                fifo_rd_ptr++;
        }

        return;
    } // End of extract
};

