            }

            XF_PTNAME(DEPTH) src_buf_temp_med_apply[WIN_SZ][XF_NPIXPERCYCLE(NPC) + (WIN_SZ - 1)];

            for (int applyfast = 0; applyfast < npc; applyfast++) {
