    // clang-format on

    float cf[5];

    float sum = 0;

    if (sigma <= 0) {
        sigma = 1.1f;
    }

    int n = 5;

    float scale2X = -(1 / ((sigma * sigma) * 2));

    for (int i = 0; i < n; i++) {
        float x = i - ((n - 1) >> 1);
        float t = expf(scale2X * x * x);

        cf[i] = (float)t;
        sum += cf[i];
    }
    float err = 0.0f;
    sum = 1. / sum;
    for (int i = 0; i < n; i++) {
        cf[i] = (float)(cf[i] * sum);
        weights[i] = ((float)(cf[i] * 256) + err + 0.5);

        err = ((cf[i] * 256)) - weights[i];
    }
}

