    ap_fixed<WIDTH, 1> cube = (sq * frac_part);
    ap_fixed<WIDTH, 1> cube_comp = cube / 6;
    ap_ufixed<WIDTH, 4> frac_out = 1 + frac_part + sq_comp + cube_comp;

    out = int_out * frac_out;
}
