                // TODO:: I included only for filter 3x3
                if (filter_width == XF_FILTER_7X7) {
                    int16_t val11 = val1 >> 9;
                    int16_t val22 = val2 >> 9;
                    dst_buf[k] = (val11 * val22) >> scale;

                } else {
                    dst_buf[k] = (val1 * val2) >> scale;
                }
            }

            tmp_dst = 0;
