/**
 * Thresholding function
 * Arguments: Input Stream, Output Stream, Threshold
 */
template <int SRC_T,
          int ROWS,
          int COLS,
          int DEPTH,
          int NPC,
          int XFCVDEPTH_IN = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_OUT = _XFCVDEPTH_DEFAULT,
