          int TC>
void xFThreshold(xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN>& _src_mat,
                 xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_OUT>& _dst_mat,
                 uint16_t threshold,
                 uint16_t img_height,
                 uint16_t img_width) {
    img_width = img_width >> XF_BITSHIFT(NPC);

    XF_SNAME(WORDWIDTH) tmp_src;
    int buf1;

Output Stream, Threshold
 */
template <int SRC_T,
          int ROWS,
          int COLS,
          int DEPTH,
          int NPC,
          int XFCVDEPTH_IN = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_OUT = _XFCVDEPTH_DEFAULT,
          int WORDWIDTH,
          int TC>
void xFThreshold(xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN>& _src_mat,
                 xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_OUT>& _dst_mat,
                 uint16_t threshold,
                 uint16_t img_height,
                 uint16_t img_width) {
    img_width = img_width >> XF_BITSHIFT(NPC);

    XF_SNAME(WORDWIDTH) tmp_src;
    int buf1;
    XF_PTNAME(DEPTH) thresh = threshold;
    int res[(1 << XF_BITSHIFT(NPC))];
    ap_uint<9> i, j;
    ap_uint<8> STEP = XF_PIXELDEPTH(XF_32UP);

Row_Loop:
    for (uint16_t row = 0; row < img_height; row++) {
// clang-format off
        #pragma HLS LOOP_TRIPCOUNT min=ROWS max=ROWS
        #pragma HLS LOOP_FLATTEN off
    // clang-format on
    Col_Loop:
        for (uint16_t col = 0; col < img_width; col++) {
// clang-format off
            #pragma HLS LOOP_TRIPCOUNT min=TC max=TC
            #pragma HLS pipeline
            // clang-format on
            tmp_src = _src_mat.read(row * img_width + col); // Read data from the input stream

        Threshold_Loop:
            for (i = 0, j = 0; i < (32 << XF_BITSHIFT(NPC)); i += 32) {
// clang-format off
                #pragma HLS unroll
                // clang-format on
                buf1 = tmp_src.range(i + 31, i);

                /*	Pack the data into result  */
                buf1 = (buf1 > thresh) ? buf1 : 0;
                res[j++] = (uint32_t)buf1;
            }

            uint16_t npc = XF_NPIXPERCYCLE(NPC);

            uint16_t shift = 0;
            tmp_src = 0;

            for (i = 0; i < npc; i++) {
// clang-format off
                #pragma HLS unroll
                // clang-format on
                uint32_t tmp = res[i];
                tmp_src = tmp_src | (((XF_SNAME(WORDWIDTH))tmp) << (shift * STEP));
                shift++;
            }
            shift = 0;

            _dst_mat.write(row * img_width + col, tmp_src); // Write data into output pixel
        }                                                   // Col_Loop

    } // Row_Loop
}
// xFThreshold

/**
 *  Compute score = det - k * trace^2
 *
 *  _src1_mat --> gx^2
 *  _src1_mat --> gx * gy
 *  _src1_mat --> gy^2
 *  _dst_mat --> Result
 */
template <int SRC_T,
          int DST_T,
          int ROWS,
          int COLS,
          int IN_DEPTH,
          int OUT_DEPTH,
