          int XFCVDEPTH_OUT = _XFCVDEPTH_DEFAULT,
          int IN_WW,
          int OUT_WW,
          int TC>
void xFComputeScore(xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_1>& _src1_mat,
                    xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_2>& _src2_mat,
                    xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_3>& _src3_mat,
                    xf::cv::Mat<DST_T, ROWS, COLS, NPC, XFCVDEPTH_OUT>& _dst_mat,
                    uint16_t img_height,
                    uint16_t img_width,

int XFCVDEPTH_IN_3 = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_OUT = _XFCVDEPTH_DEFAULT,
          int IN_WW,
          int OUT_WW,
          int TC>
void xFComputeScore(xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_1>& _src1_mat,
                    xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_2>& _src2_mat,
                    xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_3>& _src3_mat,
                    xf::cv::Mat<DST_T, ROWS, COLS, NPC, XFCVDEPTH_OUT>& _dst_mat,
                    uint16_t img_height,
                    uint16_t img_width,
                    uint16_t thresold,
                    uint8_t _filter_type) {
    img_width = img_width >> XF_BITSHIFT(NPC);
    XF_SNAME(IN_WW) tmp_src1, tmp_src2, tmp_src3;

    XF_PTNAME(OUT_DEPTH) dst_buf[(1 << XF_BITSHIFT(NPC))];
    XF_SNAME(OUT_WW) tmp_dst;
    ap_uint<8> in_step = XF_PIXELDEPTH(IN_DEPTH);
    uint16_t in_sumloop = (XF_PIXELDEPTH(IN_DEPTH) << XF_BITSHIFT(NPC));
    uint16_t npc = XF_NPIXPERCYCLE(NPC);

    ap_int<32> tmp_res[2];
    ap_int<32> det_res;
    ap_int<17> trace_res;
// clang-format off
    #pragma HLS BIND_OP variable=trace_res op=mul impl=dsp latency=2
    // clang-format on
    ap_int<50> trace_res1;
// clang-format off
    #pragma HLS BIND_OP variable=trace_res1 op=mul impl=dsp latency=2
    // clang-format on
    ap_int<32> trace_res2;
// clang-format off
    #pragma HLS BIND_OP variable=trace_res2 op=mul impl=dsp latency=2
    // clang-format on
    ap_uint<13> row, col;
    ap_uint<10> i, j;
    uint16_t shift = 0;

Row_Loop:
    for (row = 0; row < img_height; row++) {
// clang-format off
        #pragma HLS LOOP_TRIPCOUNT min=ROWS max=ROWS
        #pragma HLS LOOP_FLATTEN off
    // clang-format on
    Col_Loop:
        for (col = 0; col < img_width; col++) {
// clang-format off
            #pragma HLS LOOP_TRIPCOUNT min=TC max=TC
            #pragma HLS pipeline
            // clang-format on
            tmp_src1 = _src1_mat.read(row * img_width + col);
            tmp_src2 = _src2_mat.read(row * img_width + col);
            tmp_src3 = _src3_mat.read(row * img_width + col);

        Determinant_Loop:
            for (i = 0, j = 0; i < in_sumloop; i += in_step) {
// clang-format off
                #pragma HLS unroll
                // clang-format on
                XF_PTNAME(IN_DEPTH) val1, val2, val3;
                val1 = tmp_src1.range(i + (in_step - 1), i);
                val2 = tmp_src2.range(i + (in_step - 1), i);
                val3 = tmp_src3.range(i + (in_step - 1), i);
                // TODO:shift according to box filter
                if (_filter_type == XF_FILTER_7X7) {
                    val1 = val1 >> 0;
                    val2 = val2 >> 0;
                    val3 = val3 >> 0;
                } else {
                    val1 = val1 >> 2;
                    val2 = val2 >> 2;
                    val3 = val3 >> 2;
                }

                /* Compute determinant */

                tmp_res[0] = ((ap_int<32>)val1 * (ap_int<32>)val2);
                tmp_res[1] = ((ap_int<32>)val3 * (ap_int<32>)val3);

                det_res = tmp_res[0] - tmp_res[1];

i);
                val3 = tmp_src3.range(i + (in_step - 1), i);
                // TODO:shift according to box filter
                if (_filter_type == XF_FILTER_7X7) {
                    val1 = val1 >> 0;
                    val2 = val2 >> 0;
                    val3 = val3 >> 0;
                } else {
                    val1 = val1 >> 2;
                    val2 = val2 >> 2;
                    val3 = val3 >> 2;
                }

                /* Compute determinant */

                tmp_res[0] = ((ap_int<32>)val1 * (ap_int<32>)val2);
                tmp_res[1] = ((ap_int<32>)val3 * (ap_int<32>)val3);

                det_res = tmp_res[0] - tmp_res[1];

                /*	Compute trace */
                trace_res = val1 + val2;

                /*	Compute det - k*trace^2	 */
                trace_res1 = trace_res * trace_res;
                trace_res2 = (trace_res1 * thresold) >> 16;

                if (_filter_type == XF_FILTER_7X7) {
                    dst_buf[j++] = (XF_PTNAME(OUT_DEPTH))((det_res - trace_res2) >> 8);
                } else {
                    dst_buf[j++] = (XF_PTNAME(OUT_DEPTH))(det_res - trace_res2);
                }
            }
            tmp_dst = 0;
            xfPackPixels<NPC, OUT_WW, OUT_DEPTH>(&dst_buf[0], tmp_dst, 0, npc, shift);
            shift = 0;
            _dst_mat.write(row * img_width + col, (tmp_dst)); // Write data into output pixel
        }
    }
}
