namespace xf {
namespace cv {

template <int SRC_T,
          int DST_T,
          int ROWS,
          int COLS,
          int NPC = 1,
          int USE_URAM = 0,
          int NO_EXPS,
          int W_SIZE,
          int XFCVDEPTH_IN_1 = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_IN_2 = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_OUT = _XFCVDEPTH_DEFAULT>
void Hdrmerge_bayer(xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_1>& _src_mat1,
                    xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_2>& _src_mat2,
                    xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_OUT>& _dst_mat,
                    short wr_hls[NO_EXPS * NPC * W_SIZE]) {
    int copy_wr_hls[NO_EXPS * NPC * W_SIZE];
    for (int i = 0; i < (NO_EXPS * NPC * W_SIZE); i++) {
        copy_wr_hls[i] = wr_hls[i];
    }
    if (USE_URAM) {
#pragma HLS bind_storage variable = copy_wr_hls type = RAM_T2P impl = URAM
#pragma HLS ARRAY_PARTITION variable = copy_wr_hls factor = NPC type = block dim = 1
    } else {
#pragma HLS ARRAY_PARTITION variable = copy_wr_hls dim = 1 block factor = NO_EXPS * NPC
    }
    // clang-format off

// clang-format on	
	unsigned short width = _src_mat1.cols >> XF_BITSHIFT(NPC);
	unsigned short height = _src_mat1.rows;

	int rdindex = 0;
	int wrindex = 0;
	const int STEP = XF_DTPIXELDEPTH(SRC_T, NPC);
	XF_TNAME(SRC_T, NPC) val_src1,val_src2;
    XF_TNAME(DST_T, NPC) val_dst;

//FILE *fp1 = fopen("imagevals_hls.txt","w");
HDRmerge_LOOP:    
	for(int i = 0;i< height;i++){
// clang-format off
#pragma HLS LOOP_TRIPCOUNT min=ROWS max=ROWS
#pragma HLS LOOP_FLATTEN off
    // clang-format on		
		for(int j=0;j< width;j++){
// clang-format off
#pragma HLS LOOP_TRIPCOUNT min=COLS/NPC max=COLS/NPC
#pragma HLS pipeline
            // clang-format on
            val_src1 = (_src_mat1.read(rdindex));
            val_src2 = (_src_mat2.read(rdindex++));

            for (int p = 0, n = 0; p < XF_NPIXPERCYCLE(NPC); p++, n = NO_EXPS * p) {
// clang-format off
#pragma HLS unroll
                // clang-format on				
			XF_CTUNAME(SRC_T, NPC) val1 = val_src1.range(p * STEP + STEP - 1, p * STEP);
			XF_CTUNAME(SRC_T, NPC) val2 = val_src2.range(p * STEP + STEP - 1, p * STEP);

			int index1 = (n*W_SIZE)+val1;
			int index2 = ((n+1)*W_SIZE)+val2;

			short final_w1 =  (short)(copy_wr_hls[index1]);
			short final_w2 =  (short)(copy_wr_hls[index2]);

			ap_fixed<STEP+STEP*2,STEP+STEP> val_1 = (ap_fixed<STEP+STEP*2,STEP+STEP>)((float)(final_w1 * val1)/16384);
			ap_fixed<STEP+STEP*2,STEP+STEP> val_2 = (ap_fixed<STEP+STEP*2,STEP+STEP>)((float)(final_w2 * val2)/16384);

			ap_fixed<STEP+STEP*2,STEP+STEP> sum_wei = (ap_fixed<STEP+STEP*2,STEP+STEP>)((float)(final_w1+final_w2)/16384);

			int final_val = (int)((val_1+val_2) / sum_wei);

			XF_CTUNAME(SRC_T, NPC) out_val = xf_satcast_hdr<XF_CTUNAME(SRC_T, NPC)>(final_val);

			val_dst.range(p * STEP + STEP - 1, p * STEP) = out_val;

			}
			_dst_mat.write(wrindex++,(val_dst));
		}
		//fprintf(fp1,"\n");
	}
	//fclose(fp1);
}

template <int SRC_T,
          int DST_T,
          int ROWS,
          int COLS,
          int NPC = 1,
          int USE_URAM = 0,
          int NO_EXPS,
          int W_SIZE,
          int STREAMS = 2, 
          int XFCVDEPTH_IN_1 = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_IN_2 = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_OUT = _XFCVDEPTH_DEFAULT>
void Hdrmerge_bayer_multi(xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_1>& _src_mat1,
                    xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_2>& _src_mat2,
                    xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_OUT>& _dst_mat,
                    short wr_hls[STREAMS][NO_EXPS * NPC * W_SIZE],
                    int stream_id){



// clang-format off
    #pragma HLS ARRAY_PARTITION variable=wr_hls dim=1 complete
// clang-format on	

    Hdrmerge_bayer<SRC_T, DST_T, ROWS, COLS, NPC, USE_URAM, NO_EXPS, W_SIZE, XFCVDEPTH_IN_1, XFCVDEPTH_IN_2, 
         XFCVDEPTH_OUT>(_src_mat1, _src_mat2, _dst_mat, wr_hls[stream_id]);     
}	

