template <int SRC_T,
          int ROWS,
          int COLS,
          int DEPTH,
          int NPC,
          int XFCVDEPTH_IN_1 = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_OUT = _XFCVDEPTH_DEFAULT,
          int WORDWIDTH,
          int SRC_TC,
          int AEC_HISTSIZE>
void xFEqualize_norm_sin(xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_1>& src,
