        bj++;
    }

    else {
        xFDHOGnormalizeKernelInv(tmp_nf_sq24_2[0], nf_2[0], n_2[0]);
        xFDHOGnormalizeKernel2<NOHC, NOHCPB,

nf_1[0], n_1[0]);
        xFDHOGnormalizeKernel2<NOHC, NOHCPB, NOVCPB>(HA_1, HA_2, nf_2[0], norm_block_2, fx_rnf_sq_2[0], bj - 2, n_2[0]);
