            norm_block_1, fx_rnf_sq_1[0], _block_strm);
        flag = 0;
    }

    else {
        xFDHOGnormalizeKernel2<NOHC, NOHCPB, NOVCPB>(HA_1, HA_2, nf_1[0], norm_block_1, fx_rnf_sq_1[0], bj - 2, n_1[0]);
