            norm_block_2, fx_rnf_sq_2[0], _block_strm);
        flag = 1;
    }

    if (flag) {
        xFDHOGReNormalizeKernel<NOHC, NOHCPB, NOVCPB, NOB, ROWS, COLS, DEPTH, NPC, WORDWIDTH>(
            norm_block_1, fx_rnf_sq_1[0], _block_strm);
    } else {
        xFDHOGReNormalizeKernel<NOHC, NOHCPB, NOVCPB, NOB, ROWS, COLS, DEPTH, NPC, WORDWIDTH>(
            norm_block_2, fx_rnf_sq_2[0], _block_strm);
