                           WORDWIDTH_DST, (XF_WORDDEPTH(WORDWIDTH_SRC) / XF_WORDDEPTH(WORDWIDTH_DST)), USE_URAM>(
        _block_strm, _desc_strm, novw, nohw, novb, nohb);
