void XFIntegralImageKernel(xf::cv::Mat<SRC_TYPE, ROWS, COLS, NPC, XFCVDEPTH_IN>& _src_mat,
                           xf::cv::Mat<DST_TYPE, ROWS, COLS, NPC, XFCVDEPTH_OUT>& _dst_mat,
                           uint16_t height,
                           uint16_t width) {
// clang-format off
