    // clang-format on
    XF_SNAME(XF_32UW) linebuff[COLS];

    uint32_t cur_sum;
    ap_uint<22> prev;
    ap_uint<13> i, j;
RowLoop:
    for (i = 0; i < height; i++) {
// clang-format off
