            #pragma HLS LOOP_FLATTEN OFF
            #pragma HLS PIPELINE
            // clang-format on

            val = (XF_SNAME(XF_8UW))_src_mat.read(i * width + j);

            prev = prev + val;

            if (i == 0) {
                cur_sum = prev;
            } else {
                cur_sum = (prev + linebuff[j]);
            }

            linebuff[j] = cur_sum;
            _dst_mat.write(i * width + j, cur_sum);
        } // ColLoop

    } // rowLoop
}

