            #pragma HLS unroll
            // clang-format on
            if (idx == TA_L8 - 1 && TA_L7 % 2 == 1)
                add8_out[idx] = add7_out[2 * idx];
            else
                add8_out[idx] = add7_out[2 * idx] + add7_out[2 * idx + 1];
        }
    }

    float add_out;
    if (TA_L1 == 1)
        add_out = add1_out[0];
    else if (TA_L2 == 1)
        add_out = add2_out[0];
    else if (TA_L3 == 1)
        add_out = add3_out[0];
    else if (TA_L4 == 1)
        add_out = add4_out[0];

idx < TA_L8; idx++) {
// clang-format off
            #pragma HLS unroll
            // clang-format on
            if (idx == TA_L8 - 1 && TA_L7 % 2 == 1)
                add8_out[idx] = add7_out[2 * idx];
            else
                add8_out[idx] = add7_out[2 * idx] + add7_out[2 * idx + 1];
        }
    }

    float add_out;
    if (TA_L1 == 1)
        add_out = add1_out[0];
    else if (TA_L2 == 1)
        add_out = add2_out[0];
    else if (TA_L3 == 1)
        add_out = add3_out[0];
    else if (TA_L4 == 1)
        add_out = add4_out[0];
    else if (TA_L5 == 1)
        add_out = add5_out[0];
    else if (TA_L6 == 1)
        add_out = add6_out[0];
    else if (TA_L7 == 1)
        add_out = add7_out[0];
    else if (TA_L8 == 1)
        add_out = add8_out[0];
    else
        add_out = in1[0];

    *output = (add_out);
}

template <int PROC>
void KF_scaleSub(float in1[PROC], float scale, float in2[PROC], float out[PROC]) {
// clang-format off
    #pragma HLS ARRAY_PARTITION variable=in1 complete dim=1
    #pragma HLS ARRAY_PARTITION variable=in2 complete dim=1
    #pragma HLS ARRAY_PARTITION variable=out complete dim=1
    #pragma HLS inline off
    // clang-format on

    float scale_neg = -scale;

    for (int idx = 0; idx < PROC; idx++) {
// clang-format off
        #pragma HLS unroll
        // clang-format on
        out[idx] = in1[idx] + (scale_neg * in2[idx]);
    }
}

template <int PROC>
void KF_scale(float in[PROC], float scale, float out[PROC]) {
// clang-format off
    #pragma HLS ARRAY_PARTITION variable=in complete dim=1
    #pragma HLS ARRAY_PARTITION variable=out complete dim=1
    #pragma HLS inline off
    // clang-format on
    for (int idx = 0; idx < PROC; idx++) {
// clang-format off
        #pragma HLS unroll
        // clang-format on
        out[idx] = scale * in[idx];
    }
}

template <int PROC>
void KF_add(float in1[PROC], float in2[PROC], float out[PROC]) {
// clang-format off
    #pragma HLS ARRAY_PARTITION variable=in1 complete dim=1
    #pragma HLS ARRAY_PARTITION variable=in2 complete dim=1
    #pragma HLS ARRAY_PARTITION variable=out complete dim=1
    #pragma HLS inline off
    // clang-format on
    for (int idx = 0; idx < PROC; idx++) {
// clang-format off
        #pragma HLS unroll
        // clang-format on
        out[idx] = in1[idx] + in2[idx];
    }
}

