          int XFCVDEPTH_UOUT = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_DOUT = _XFCVDEPTH_DEFAULT>
void TimeUpdate(float T_matrix[PROC_TU][TMAT_DEPTH],
                float AB_matrix[PROC_MU][ABMAT_DEPTH],
                float xu_vector[512],
                float U_matrix[PROC_MU][UMAT_DEPTH],
