    if (X_write_en) KF_X_write<N_STATE, TYPE, NPC, XFCVDEPTH_XOUT>(xu_vector, Xout_mat);

    if (UD_write_en)
        KF_UD_write<N_STATE, PROC_MU, DEPTH_MU, UMAT_DEPTH, TYPE, NPC, XFCVDEPTH_UOUT, XFCVDEPTH_DOUT>(
            U_matrix, D_vector, Uout_mat, Dout_mat);
