            block = 4;
            tmpx = x2;
            for (tmp = 0; tmp < 4; tmp++) {
// clang-format off
                #pragma HLS LOOP_TRIPCOUNT min=4 max=4 avg=4
                #pragma HLS pipeline
                // clang-format on
                tmpx = x2 >> (3 - tmp);
                if (tmpx) {
                    pos = tmp + 1;
                    break;
                }
            }
        } else if (x3 > 0) {
            block = 8;
            tmpx = x3;
            for (tmp = 0; tmp < 4; tmp++) {
// clang-format off
                #pragma HLS LOOP_TRIPCOUNT min=4 max=4 avg=4
                #pragma HLS pipeline
                // clang-format on
                tmpx = x3 >> (3 - tmp);
                if (tmpx) {
                    pos = tmp + 1;
                    break;
                }
            }
        } else {
            block = 12;
            tmpx = x4;
            for (tmp = 0; tmp < 4; tmp++) {
// clang-format off
                #pragma HLS LOOP_TRIPCOUNT min=4 max=4 avg=4
                #pragma HLS pipeline
                // clang-format on
                tmpx = x4 >> (3 - tmp);
                if (tmpx) {
                    pos = tmp + 1;
                    break;
                }
            }
        }
    }
    B_L = block + pos;
    shift = 0; // DATA_SIZE - LUT_BITS - 1;
    if (B_L >= 1) {
        index = ((x << (B_L - 1)) & 0x7FFF) >> shift;
    } else {
