    val = division_lut32[index];

    *N = M + 16 - B_L;

    return val;
}

static unsigned int Inverse(unsigned short x, int M, char* N) {
#pragma HLS inline off
    assert((M <= 16) && "Integer part of x should always be less than or equal to 16 bits.

");
    unsigned int val = 0;
    unsigned int index;
    int B_L = DATA_SIZE + 1;

    //  int tmp = 4;
    int pos, block;
    pos = block = 0;
    int shift = 0;
    unsigned short x1 = (x >> 12) & 0x000F;
    unsigned short x2 = (x >> 8) & 0x000F;
    unsigned short x3 = (x >> 4) & 0x000F;
    unsigned short x4 = x & 0x000F;

    unsigned short tmpx = 0;

    unsigned short x_sel;
    if (x1 > 0) {
        block = 0;
        x_sel = x1;
    } else if (x2 > 0) {
        block = 1;
        x_sel = x2;
    } else if (x3 > 0) {
        block = 2;
        x_sel = x3;
    } else {
        block = 3;
        x_sel = x4;
    }

    unsigned short tmpx_0 = x_sel >> (3 - 0);
    unsigned short tmpx_1 = x_sel >> (3 - 1);
    unsigned short tmpx_2 = x_sel >> (3 - 2);
    unsigned short tmpx_3 = x_sel >> (3 - 3);

    if (tmpx_0)
        pos = 1;
    else if (tmpx_1)
        pos = 2;
    else if (tmpx_2)
        pos = 3;
    else if (tmpx_3)
        pos = 4;

    B_L = 4 * block + pos;
    shift = DATA_SIZE - LUT_BITS;
    index = ((x << (B_L - 1)) & 0x7FFF) >> shift;

    val = division_lut[index];
    *N = M + DATA_SIZE - B_L;

    return val;
}

static char IdentifySignBits(ap_int<24> in_val) {
    bool flag = 0;
    char counter = 0;

    bool signbit = in_val.range(23, 23);

signBitsLoop:
    while (flag == 0) {
// clang-format off
        #pragma HLS LOOP_TRIPCOUNT min=24 max=24
        #pragma HLS PIPELINE
        // clang-format on

        bool bit_val = in_val.range((23 - counter), (23 - counter));

        if (bit_val == signbit)
            counter++;
        else
            flag = 1;

        if (counter == 24) break;
    }
    return counter;
}

