    // clang-format on

    uint16_t _min_locx, _min_locy, _max_locx, _max_locy;
    int32_t _min_val, _max_val;
    uint16_t height = _src.rows;
    uint16_t width = _src.cols >> XF_BITSHIFT(NPC);

    xFMinMaxLocKernel<SRC_T, ROWS, COLS, XF_DEPTH(SRC_T, NPC), NPC, XFCVDEPTH_IN, XF_WORDWIDTH(SRC_T, NPC),
                      (COLS >> XF_BITSHIFT(NPC))>(_src, _min_val, _max_val, _min_locx, _min_locy, _max_locx, _max_locy,
                                                  height, width);

    *min_value = _min_val;
    *max_value = _max_val;

#endif
// clang-format off
    #pragma HLS inline off
    // clang-format on

    uint16_t _min_locx, _min_locy, _max_locx, _max_locy;
    int32_t _min_val, _max_val;
    uint16_t height = _src.rows;
    uint16_t width = _src.cols >> XF_BITSHIFT(NPC);

    xFMinMaxLocKernel<SRC_T, ROWS, COLS, XF_DEPTH(SRC_T, NPC), NPC, XFCVDEPTH_IN, XF_WORDWIDTH(SRC_T, NPC),
                      (COLS >> XF_BITSHIFT(NPC))>(_src, _min_val, _max_val, _min_locx, _min_locy, _max_locx, _max_locy,
                                                  height, width);

    *min_value = _min_val;
    *max_value = _max_val;
    *_minlocx = _min_locx;
    *_minlocy = _min_locy;
    *_maxlocx = _max_locx;
    *_maxlocy = _max_locy;
}
