template <unsigned int ROWS,
          unsigned int COLS,
          unsigned int TYPE,
          unsigned int NPC,
          int XFCVDEPTH_IN = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_OUT = _XFCVDEPTH_DEFAULT,
          int PLANES,
          bool USE_URAM>
void xFpyrDownKernel(xf::cv::Mat<TYPE, ROWS, COLS, NPC, XFCVDEPTH_IN>& _src,
                     xf::cv::Mat<TYPE, (ROWS / 2), (COLS / 2), NPC, XFCVDEPTH_OUT>& _dst,
                     unsigned short in_rows,
                     unsigned short in_cols) {
// clang-format off
    #pragma HLS DATAFLOW
    // clang-format on
    hls::stream<XF_TNAME(TYPE, NPC)> _filter_in;
    hls::stream<XF_TNAME(TYPE, NPC)> _filter_out;
    unsigned int read_pointer = 0;
    for (int i = 0; i < in_rows; i++) {
// clang-format off
        #pragma HLS LOOP_TRIPCOUNT min=1 max=ROWS
        // clang-format on
        for (int j = 0; j < in_cols; j++) {
// clang-format off
            #pragma HLS LOOP_TRIPCOUNT min=1 max=COLS
            #pragma HLS PIPELINE II=1
            // clang-format on
            _filter_in.write(_src.read(read_pointer));
            read_pointer++;
        }
    }
    xFPyrDownGaussianBlur<ROWS, COLS, TYPE, NPC, XF_WORDWIDTH(TYPE, NPC), 0, 5, 25, PLANES>(
        _filter_in, _filter_out, 5, XF_BORDER_CONSTANT, in_rows, in_cols);

    unsigned int write_ptr = 0;
    for (int i = 0; i < in_rows; i++) {
// clang-format off
        #pragma HLS LOOP_TRIPCOUNT min=1 max=ROWS
        // clang-format on
        for (int j = 0; j < in_cols; j++) {
// clang-format off
            #pragma HLS LOOP_TRIPCOUNT min=1 max=COLS
            #pragma HLS PIPELINE II=1
            // clang-format on
            XF_TNAME(TYPE, NPC) read_fil_out = _filter_out.read();
            if (i % 2 == 0 && j % 2 == 0) {
                _dst.write(write_ptr, read_fil_out);
                write_ptr++;
            }
        }
    }
    return;
}

template <int TYPE,
          int ROWS,
          int COLS,
          int NPC,
          bool USE_URAM = false,
          int XFCVDEPTH_IN = _XFCVDEPTH_DEFAULT,
          int XFCVDEPTH_OUT = _XFCVDEPTH_DEFAULT>
void pyrDown(xf::cv::Mat<TYPE, ROWS, COLS, NPC, XFCVDEPTH_IN>& _src,
             xf::cv::Mat<TYPE, (ROWS / 2), (COLS / 2), NPC, XFCVDEPTH_OUT>& _dst) {
// clang-format off
    #pragma HLS INLINE OFF
    // clang-format on
    unsigned short input_height = _src.rows;
    unsigned short input_width = _src.cols;
    xFpyrDownKernel<ROWS, COLS, TYPE, NPC, XFCVDEPTH_IN, XFCVDEPTH_OUT, XF_CHANNELS(TYPE, NPC), USE_URAM>(
        _src, _dst, input_height, input_width);
    return;
}
