constexpr unsigned XF_LOG2(unsigned x) {
    return (x < 2) ? 0 : 1 + XF_LOG2(x >> 1);
}

template <int OUT_TYPE>
bool isPowerOfTwo(int n) {
    if (n == 0) return 0;
    while (n != 1) {
        if (n % 2 != 0) return 0;
        n = n / 2;
    }
    return 1;
}

