        // clang-format on
        if (REDUCE_OP == REDUCE_MIN) {
            internal_res = -1;
            max = 255;
        } else {
            internal_res = 0;
            max = 0;
        }
    colLoop:
        for (j = 0; j < width; j++) {
// clang-format off
            #pragma HLS LOOP_TRIPCOUNT min=COLS_TRIP max=COLS_TRIP
            #pragma HLS pipeline
            // clang-format on

            val_src =
                (XF_SNAME(WORDWIDTH_SRC))(_src_mat.read(i * width + j)); // reading the source stream _src into val_src
            if (dim == 0) {
                internal_res = line_buf[j];
            }

            switch (REDUCE_OP) {
                case REDUCE_SUM:
                    internal_res = internal_res + val_src;
                    break;
                case REDUCE_AVG:
                    internal_res = internal_res + val_src;
                    break;
                case REDUCE_MAX:
                    internal_res =
                        ((XF_SNAME(WORDWIDTH_SRC))internal_res > val_src ? (XF_SNAME(WORDWIDTH_SRC))internal_res
                                                                         : val_src);
                    break;
                case REDUCE_MIN:
                    internal_res =
                        ((XF_SNAME(WORDWIDTH_SRC))internal_res < val_src ?

(XF_SNAME(WORDWIDTH_SRC))internal_res
