    XF_TNAME(SRC_T, NPC) RGB[XF_NPIXPERCYCLE(NPC)];
    ap_uint<8> r, g, b;
    int h;
    int s, v;
    ap_uint<8> vmin;
    ap_uint<8> diff;
    int vr, vg;

    for (uint16_t row = 0; row < _src_mat.rows; row++) {
// clang-format off
        #pragma HLS LOOP_TRIPCOUNT max=ROWS
        // clang-format on
        for (uint16_t col = 0; col < (_src_mat.cols >> XF_BITSHIFT(NPC)); col++) {
