            #pragma HLS PIPELINE
            // clang-format on

            in_pix = _src_mat.read(row * (_src_mat.cols >> XF_BITSHIFT(NPC)) + col);

            for (int k = 0; k < XF_NPIXPERCYCLE(NPC); k++) {
                RGB[k] = in_pix.range(k * XF_PIXELWIDTH(SRC_T, NPC) + (XF_PIXELWIDTH(SRC_T, NPC) - 1),
                                      k * XF_PIXELWIDTH(SRC_T, NPC));

                r = RGB[k].range(7, 0);
                g = RGB[k].range(15, 8);
                b = RGB[k].range(23, 16);

                v = b;
                vmin = b;

                CV_CALC_MAX_8U(v, g);
                CV_CALC_MAX_8U(v, r);
                CV_CALC_MIN_8U(vmin, g);
                CV_CALC_MIN_8U(vmin, r);

                diff = v - vmin;
                vr = v == r ? -1 : 0;
                vg = v == g ? -1 : 0;

                s = (diff * sdiv[v] + (1 << (11))) >> 12;
                h = (vr & (g - b)) + (~vr & ((vg & (b - r + 2 * diff)) + ((~vg) & (r - g + 4 * diff))));
                h = (h * hdiv[diff] + (1 << (11))) >> 12;
                h += h < 0 ? 180 : 0;

                out_pix[k].range(7, 0) = (unsigned char)h;
                out_pix[k].range(15, 8) = (unsigned char)s;
                out_pix[k].range(23, 16) = (unsigned char)v;
                HSV_packed.range(k * XF_PIXELWIDTH(SRC_T, NPC) + (XF_PIXELWIDTH(SRC_T, NPC) - 1),
                                 k * XF_PIXELWIDTH(SRC_T, NPC)) = out_pix[k];
