                    imgblock[2][__BWIDTH - NPPC + r] = 0;
                    imgblock[3][__BWIDTH - NPPC + r] = 0;
                    imgblock[4][__BWIDTH - NPPC + r] = 0;
                }
            }

        } // end COL loop
    }     // end ROW loop
}

