    XF_PTNAME(DEPTH_DST) g_y;
    // ap_uint<8> g_y;
    short int temp_g;
    short int M00 = (short int)vb1 << 3;
    M00 = M00 + vb1 + vb1;
    short int M01 = (short int)vt1 << 3;
    M01 = M01 + vt1 + vt1;
    short int A00 = (short int)vb0 << 1;
    A00 = A00 + vb0;
    short int A01 = (short int)vb2 << 1;
    A01 = A01 + vb2;
    A00 = A00 + A01;
    short int S00 = (short int)vt0 << 1;
    S00 = S00 + vt0;
    short int S01 = (short int)vt2 << 1;
    S01 = S01 + vt2;
    S00 = S00 + S01;

short int M00 = (short int)vb1 << 3;
    M00 = M00 + vb1 + vb1;
    short int M01 = (short int)vt1 << 3;
    M01 = M01 + vt1 + vt1;
    short int A00 = (short int)vb0 << 1;
    A00 = A00 + vb0;
    short int A01 = (short int)vb2 << 1;
    A01 = A01 + vb2;
    A00 = A00 + A01;
    short int S00 = (short int)vt0 << 1;
    S00 = S00 + vt0;
    short int S01 = (short int)vt2 << 1;
    S01 = S01 + vt2;
