    // clang-format on

    XF_PTNAME(DEPTH_DST) g_x = 0;
    // ap_uint<8> g_x = 0;
    short int M00 = ((short int)m0 << 1);
    short int M01 = ((short int)m2 << 1);
    short int A00 = (t2 + b2);
    short int S00 = (t0 + b0);

    short int out_pix;
    out_pix = M01 - M00;
    out_pix = out_pix + A00;
    out_pix = out_pix - S00;

