void xFSobelFilter7x7(xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN>& _src_mat,
                      xf::cv::Mat<DST_T, ROWS, COLS, NPC, XFCVDEPTH_OUT_X>& _gradx_mat,
