          int DC_SIZE,
          int MAP_T,
          int ROWS,
          int COLS,
          int NPC,
          int XFCVDEPTH_mapx = _XFCVDEPTH_DEFAULT,

1 + BitWidth<ROWS>::Value, AP_RND, AP_SAT>, CM_T,
                CM_SIZE, N>(cameraMatrixHLS, distCoeffsHLS, iRnewCameraMatrixHLS, noRotation, ifixed, jfixed, u, v);

            float mx = (float)u;
