void xFReadOutStream(xf::cv::Mat<SRC_T, ROWS, COLS, 1, XFCVDEPTH_IN>& src, short int height, short int width) {
loop_row_clip:
    for (short i = 0; i < height;

tmp_out.range((k + 1) * XF_PIXELDEPTH(DEPTH_DST) - 1, k * XF_PIXELDEPTH(DEPTH_DST)) =
                    (XF_PTNAME(DEPTH_DST))p;
            }
            dst.write(tmp_out);
