    // clang-format on
    //	const int COLS = COLS;
    //	const int STORE_LINES = Num_Store_Rows;
    // finding if i and j are even or odd to access the appropriate memory
    bool i_a1 = (i & 0x00000002) >> 1;
    bool i_a = i & 0x00000001;
    bool j_a = j & 0x00000001;
    ap_uint<16> I = ap_uint<16>(i >> 2);
